mapper.select:
SELECT material_type_code
FROM tb_material_info
WHERE material_id = #{id, jdbcType=BIGINT}
  AND tenant_id = #{tenantId, jdbcType=BIGINT}
  AND delete_status = 'N'
  AND deleted_at IS NULL

INSERT INTO tb_purchase_request_hd (
    tenant_id, request_no, request_dt, requester_id, request_dept_id,
    status, total_amt, remark, created_by
) VALUES (
    #{tenantId}, #{requestNo}, CAST(#{requestDt} AS date), #{requesterId}, #{requestDeptId, jdbcType=BIGINT},
    #{status}, 0, #{remark}, #{createdBy}
)
RETURNING purchase_request_id

INSERT INTO tb_purchase_request_dt (
    purchase_request_id, tenant_id, line_no, material_id, request_qty,
    request_delivery_dt, use_type, request_remark, created_by
) VALUES (
    #{purchaseRequestId}, #{tenantId}, #{lineNo}, #{materialId}, #{requestQty},
    CAST(#{requestDeliveryDt} AS date), #{useType}, #{requestRemark}, #{createdBy}
)
RETURNING purchase_request_detail_id

mapper.update:
UPDATE tb_purchase_request_dt
SET line_no = line_no + 100000
WHERE purchase_request_id = #{purchaseRequestId, jdbcType=BIGINT}
  AND tenant_id = #{tenantId, jdbcType=BIGINT}

mapper.delete:
DELETE FROM tb_purchase_request_dt
WHERE purchase_request_detail_id = #{purchaseRequestDetailId, jdbcType=BIGINT}
  AND purchase_request_id = #{purchaseRequestId, jdbcType=BIGINT}
  AND tenant_id = #{tenantId, jdbcType=BIGINT}
